if (ctx.geo == null) { return; }
String[] fields = new String[] {'location', 'peak_signal_location'};
for (int i = 0; i < fields.length; i++) {
  def p = ctx.geo.get(fields[i]);
  if (p == null) { continue; }
  boolean valid = false;
  if (p instanceof Map) {
    def a = p.get('lat'); def o = p.get('lon');
    if (a instanceof Number && o instanceof Number) {
      double lat = a.doubleValue(); double lon = o.doubleValue();
      valid = lat >= -90.0 && lat <= 90.0 && lon >= -180.0 && lon <= 180.0 && !(lat == 0.0 && lon == 0.0);
    }
  }
  if (!valid) {
    ctx.geo.remove(fields[i]);
    if (fields[i] == 'location') { ctx.geo.remove('location_type'); ctx.geo.put('status', 'invalid'); }
  }
}
